/**
 * The create-agent interview as data. The CLI prompts from it, answers files
 * validate against schemas built from it, and the create-agent skill's round
 * tables are rendered from it.
 */
import * as z from "zod/v4";
import { DEFAULT_MODEL } from "../../types.js";
import { NAME_PATTERN, RESERVED_SLUGS } from "../discovery/names.js";
import { field } from "./question.js";
export const PURPOSES = [
    "chat",
    "repo-automation",
    "domain-assistant",
    "scheduled-reporter",
    "other",
];
export const CHANNELS = ["slack", "github", "webhook", "schedule"];
export const MCP_KINDS = ["cursor-account", "remote", "stdio"];
export const CAPABILITIES = [
    "server-tools",
    "agent-tools",
    "skills",
    "subagents",
    "hooks",
    "sandbox-seeds",
    "evals",
];
function isPurpose(value) {
    return PURPOSES.some((purpose) => purpose === value);
}
const PURPOSE_CHANNELS = {
    chat: "slack",
    "repo-automation": "github",
    "domain-assistant": "none",
    "scheduled-reporter": "schedule",
    other: "none",
};
const MODEL = typeof DEFAULT_MODEL === "string" ? { id: DEFAULT_MODEL } : DEFAULT_MODEL;
const MODEL_PARAMS = MODEL.params ?? [];
const MODEL_LABEL = `\`${MODEL.id}\` + ${MODEL_PARAMS.map((p) => `\`${p.id}=${p.value}\``).join(", ")}`;
export const DEFAULT_MODEL_ID = MODEL.id;
export const agentName = z
    .string()
    .regex(NAME_PATTERN, `must match ${NAME_PATTERN}.`)
    .refine((name) => !RESERVED_SLUGS.has(name), {
    message: `must not be ${[...RESERVED_SLUGS].join(", ")}.`,
});
export const AGENT_FIELDS = [
    field("identity", { id: "purpose", label: "Purpose", prompt: "What is the agent for?", choices: [...PURPOSES] }, z.enum(PURPOSES), "chat assistant · PR / repo automation · domain assistant over APIs/tools · scheduled reporter · Other"),
    field("identity", {
        id: "name",
        label: "Name",
        prompt: "Agent name (also its directory)?",
        hint: "Directory: `[A-Za-z0-9][A-Za-z0-9_-]*`, not `v1`/`playground`/`docs`",
    }, agentName, "2–3 slugs from the purpose + Other"),
    field("identity", {
        id: "location",
        label: "Location",
        prompt: "Directory to scaffold into?",
        default: (answers) => (answers.name === undefined ? undefined : `./${answers.name}`),
    }, z.string().min(1), "`./<slug>` (default) · another directory"),
    field("surface", {
        id: "model",
        label: "Model",
        prompt: "Model id?",
        hint: `Params, not id suffixes: \`{ id: "${MODEL.id}", params: [${MODEL_PARAMS.map((p) => `{ id: "${p.id}", value: "${p.value}" }`).join(", ")}] }\``,
        choices: [{ value: MODEL.id, label: MODEL_LABEL }],
        other: true,
        default: MODEL.id,
    }, z.string().min(1), `${MODEL_LABEL} · Other id`),
    field("surface", {
        id: "channels",
        label: "Channels",
        prompt: "Channels beyond the playground and HTTP?",
        hint: "Slack: `skills/setup-slack/SKILL.md`. GitHub: `skills/github/SKILL.md`. No Discord/Teams pack; offer custom webhook.",
        multi: true,
        choices: [
            { value: "slack", label: "Slack" },
            { value: "github", label: "GitHub" },
            { value: "webhook", label: "custom webhook" },
            { value: "schedule", label: "schedule" },
        ],
        default: (answers) => isPurpose(answers.purpose) ? PURPOSE_CHANNELS[answers.purpose] : "none",
    }, z.array(z.enum(CHANNELS)), "playground + HTTP (always on) · Slack · GitHub · custom webhook · schedule"),
    field("surface", {
        id: "mcp",
        label: "MCP",
        prompt: "MCP connections?",
        hint: "One file under `bot/mcp-connections/`. Account file is `account.ts`, never `cursor.ts`. Named local tools need `advertiseTools: true`. Privileged servers go in `bot/host-connections/`.",
        multi: true,
        choices: [...MCP_KINDS],
        default: (answers) => (answers.purpose === "domain-assistant" ? "cursor-account" : "none"),
    }, z.array(z.enum(MCP_KINDS)), "none · remote URL · local stdio · Cursor account connectors · Other"),
    field("surface", {
        id: "capabilities",
        label: "Capabilities",
        prompt: "Capabilities?",
        hint: "Always recommend one smoke eval.",
        multi: true,
        choices: [...CAPABILITIES],
        default: "evals",
    }, z.array(z.enum(CAPABILITIES)), "server tools · agent tools · skills · subagents · hooks · sandbox seeds · evals (recommend)"),
];
const ROUND_TITLES = {
    identity: "Round 1: identity",
    surface: "Round 2: surface",
};
/** The create-agent skill's interview tables. */
export function renderInterviewTables() {
    return ["identity", "surface"]
        .map((round) => [
        `### ${ROUND_TITLES[round]}`,
        "",
        "| Question | Options | Guidance |",
        "| --- | --- | --- |",
        ...AGENT_FIELDS.filter((f) => f.round === round).map(tableRow),
    ].join("\n"))
        .join("\n\n");
}
function tableRow({ question, options }) {
    const label = `**${question.label ?? question.id}**${question.multi ? " (multi)" : ""}`;
    return `| ${label} | ${options ?? ""} | ${question.hint ?? ""} |`;
}
